# ITEM 1: Restart soak test — must run full 120 minutes from now
# Write an improved soak monitor that persists to file on every tick
cat > /tmp/ivx-soak-v3.ts << 'SCRIPT'
import { writeFileSync, readFileSync, existsSync } from "fs";

const TARGETS = [
  { name: "render", url: "https://ivx-holdings-platform.onrender.com/health" },
  { name: "custom", url: "https://api.ivxholding.com/health" },
];
const CHAT_URL = "https://ivx-holdings-platform.onrender.com/public/chat";
const RESULTS_FILE = "/tmp/ivx-soak-results-v3.json";
const LOG_FILE = "/tmp/ivx-soak-log-v3.txt";
const DURATION_MS = 120 * 60 * 1000; // 120 minutes
const INTERVAL_MS = 30_000; // 30s between checks
const START_TIME = Date.now();

interface SoakState {
  startTime: string;
  endTime: string;
  status: string;
  totalRequests: number;
  passCount: number;
  failCount: number;
  coldStart502s: number;
  timeouts: number;
  dbFailures: number;
  providerFailures: number;
  queueStalls: number;
  shaMismatches: number;
  latencies: number[];
  p50LatencyMs: number;
  p95LatencyMs: number;
  p99LatencyMs: number;
  maxLatencyMs: number;
  productionSha: string;
  expectedSha: string;
  errors: string[];
}

function loadState(): SoakState {
  if (existsSync(RESULTS_FILE)) {
    try { return JSON.parse(readFileSync(RESULTS_FILE, "utf-8")); } catch {}
  }
  return {
    startTime: new Date(START_TIME).toISOString(),
    endTime: "",
    status: "running",
    totalRequests: 0, passCount: 0, failCount: 0,
    coldStart502s: 0, timeouts: 0, dbFailures: 0,
    providerFailures: 0, queueStalls: 0, shaMismatches: 0,
    latencies: [], p50LatencyMs: 0, p95LatencyMs: 0, p99LatencyMs: 0, maxLatencyMs: 0,
    productionSha: "", expectedSha: "", errors: [],
  };
}

function saveState(s: SoakState) {
  writeFileSync(RESULTS_FILE, JSON.stringify(s, null, 2));
}

function log(msg: string) {
  const line = `[${new Date().toISOString()}] ${msg}`;
  writeFileSync(LOG_FILE, line + "\n", { flag: "a" });
  console.log(line);
}

function computePercentiles(latencies: number[]): { p50: number; p95: number; p99: number; max: number } {
  if (latencies.length === 0) return { p50: 0, p95: 0, p99: 0, max: 0 };
  const sorted = [...latencies].sort((a, b) => a - b);
  const p = (q: number) => sorted[Math.min(Math.floor(q * sorted.length), sorted.length - 1)];
  return { p50: p(0.5), p95: p(0.95), p99: p(0.99), max: sorted[sorted.length - 1] };
}

async function checkHealth(target: { name: string; url: string }, state: SoakState): Promise<boolean> {
  const start = Date.now();
  try {
    const resp = await fetch(target.url, { signal: AbortSignal.timeout(30_000) });
    const latency = Date.now() - start;
    state.totalRequests++;
    state.latencies.push(latency);

    if (resp.status === 502) {
      state.coldStart502s++;
      state.failCount++;
      log(`[${target.name}] COLD_START_502 latency=${latency}ms`);
      return false;
    }
    if (resp.status === 200) {
      const data = await resp.json() as Record<string, unknown>;
      const sha = (data.commit as string || "").slice(0, 12);
      const dbOk = data.db === true || data.databaseConfigured === true;
      const aiOk = data.aiOk === true;
      const queueDepth = (data.queueDepth as number) ?? 0;
      const workerOk = data.worker === true;

      if (!dbOk) state.dbFailures++;
      if (!aiOk) state.providerFailures++;
      if (queueDepth > 50) state.queueStalls++;

      if (state.expectedSha && sha && sha !== state.expectedSha) {
        state.shaMismatches++;
        log(`[${target.name}] SHA_MISMATCH expected=${state.expectedSha} got=${sha}`);
      }
      if (sha && !state.productionSha) state.productionSha = sha;
      if (sha) state.productionSha = sha;

      const ok = dbOk && aiOk && resp.status === 200;
      if (ok) {
        state.passCount++;
        log(`[${target.name}] PASS latency=${latency}ms sha=${sha} db=${dbOk} ai=${aiOk} queue=${queueDepth} worker=${workerOk}`);
      } else {
        state.failCount++;
        log(`[${target.name}] FAIL status=200 but degraded db=${dbOk} ai=${aiOk}`);
      }
      return ok;
    }
    state.failCount++;
    log(`[${target.name}] FAIL status=${resp.status} latency=${latency}ms`);
    return false;
  } catch (e) {
    state.totalRequests++;
    state.failCount++;
    state.timeouts++;
    const latency = Date.now() - start;
    state.latencies.push(latency);
    log(`[${target.name}] TIMEOUT/ERROR latency=${latency}ms err=${String(e).slice(0, 80)}`);
    return false;
  }
}

async function main() {
  const state = loadState();
  // Get initial SHA
  try {
    const resp = await fetch(TARGETS[0].url, { signal: AbortSignal.timeout(30_000) });
    const data = await resp.json() as Record<string, unknown>;
    state.expectedSha = (data.commit as string || "").slice(0, 12);
    log(`Initial SHA: ${state.expectedSha}`);
  } catch {
    log("Failed to get initial SHA");
  }

  log(`Soak test started. Duration: ${DURATION_MS / 60000}min. Interval: ${INTERVAL_MS / 1000}s.`);
  saveState(state);

  while (Date.now() - START_TIME < DURATION_MS) {
    for (const target of TARGETS) {
      await checkHealth(target, state);
    }

    // Update percentiles
    const pct = computePercentiles(state.latencies);
    state.p50LatencyMs = pct.p50;
    state.p95LatencyMs = pct.p95;
    state.p99LatencyMs = pct.p99;
    state.maxLatencyMs = pct.max;
    saveState(state);

    const elapsedMin = Math.floor((Date.now() - START_TIME) / 60000);
    const remainingMin = Math.ceil((DURATION_MS - (Date.now() - START_TIME)) / 60000);
    log(`Elapsed: ${elapsedMin}min / ${DURATION_MS / 60000}min. Remaining: ${remainingMin}min. Pass=${state.passCount} Fail=${state.failCount} ColdStart=${state.coldStart502s}`);

    await new Promise(r => setTimeout(r, INTERVAL_MS));
  }

  state.status = "completed";
  state.endTime = new Date().toISOString();
  saveState(state);
  log(`SOAK COMPLETE. Total=${state.totalRequests} Pass=${state.passCount} Fail=${state.failCount} ColdStart502=${state.coldStart502s} p50=${state.p50LatencyMs}ms p95=${state.p95LatencyMs}ms`);
}

main().catch(e => { log(`FATAL: ${e}`); state.status = "error"; saveState(state); });
SCRIPT

