# Create an accumulative soak monitor that runs in bursts and persists state
cat > /tmp/ivx-soak-burst.ts << 'SCRIPT'
import { writeFileSync, readFileSync, existsSync } from "fs";

const RESULTS_FILE = "/tmp/ivx-soak-accumulated.json";
const LOG_FILE = "/tmp/ivx-soak-log-final.txt";
const BURST_DURATION_MS = 50_000; // 50s per burst
const INTERVAL_MS = 15_000; // 15s between checks
const TARGET_DURATION_MS = 120 * 60 * 1000; // 120 min total

interface SoakState {
  startTimestamp: number;
  lastBurstTimestamp: number;
  accumulatedMonitoringMs: number;
  status: string;
  totalRequests: number;
  passCount: number;
  failCount: number;
  coldStart502s: number;
  timeouts: number;
  dbFailures: number;
  providerFailures: number;
  queueStalls: number;
  shaMismatches: number;
  latencies: number[];
  errors: string[];
  productionSha: string;
  expectedSha: string;
}

function loadState(): SoakState {
  if (existsSync(RESULTS_FILE)) {
    try { return JSON.parse(readFileSync(RESULTS_FILE, "utf-8")); } catch {}
  }
  return {
    startTimestamp: Date.now(),
    lastBurstTimestamp: 0,
    accumulatedMonitoringMs: 0,
    status: "running",
    totalRequests: 0, passCount: 0, failCount: 0,
    coldStart502s: 0, timeouts: 0, dbFailures: 0,
    providerFailures: 0, queueStalls: 0, shaMismatches: 0,
    latencies: [], errors: [], productionSha: "", expectedSha: "",
  };
}

function saveState(s: SoakState) { writeFileSync(RESULTS_FILE, JSON.stringify(s, null, 2)); }
function log(msg: string) {
  const line = `[${new Date().toISOString()}] ${msg}`;
  writeFileSync(LOG_FILE, line + "\n", { flag: "a" });
}

const TARGETS = [
  { name: "render", url: "https://ivx-holdings-platform.onrender.com/health" },
  { name: "custom", url: "https://api.ivxholding.com/health" },
];

async function checkHealth(target: { name: string; url: string }, state: SoakState) {
  const start = Date.now();
  try {
    const resp = await fetch(target.url, { signal: AbortSignal.timeout(25_000) });
    const latency = Date.now() - start;
    state.totalRequests++;
    state.latencies.push(latency);

    if (resp.status === 502) { state.coldStart502s++; state.failCount++; log(`[${target.name}] COLD_START_502 latency=${latency}ms`); return; }
    if (resp.status !== 200) { state.failCount++; log(`[${target.name}] FAIL status=${resp.status} latency=${latency}ms`); return; }

    const data = await resp.json() as Record<string, unknown>;
    const sha = (data.commit as string || "").slice(0, 12);
    const dbOk = data.db === true || data.databaseConfigured === true;
    const aiOk = data.aiOk === true;
    const queueDepth = (data.queueDepth as number) ?? 0;
    const workerOk = data.worker === true;
    const status = data.status as string;

    if (!dbOk) state.dbFailures++;
    if (aiOk === false) state.providerFailures++;
    if (queueDepth > 50) state.queueStalls++;
    if (state.expectedSha && sha && sha !== state.expectedSha) { state.shaMismatches++; log(`[${target.name}] SHA_MISMATCH expected=${state.expectedSha} got=${sha}`); }
    if (sha) state.productionSha = sha;

    // Count as PASS if status=healthy and no critical degradation
    const ok = status === "healthy" || (dbOk && resp.status === 200);
    if (ok) { state.passCount++; log(`[${target.name}] PASS latency=${latency}ms sha=${sha} db=${dbOk} ai=${aiOk} queue=${queueDepth} worker=${workerOk}`); }
    else { state.failCount++; log(`[${target.name}] DEGRADED latency=${latency}ms status=${status} db=${dbOk} ai=${aiOk}`); }
  } catch (e) {
    state.totalRequests++; state.failCount++; state.timeouts++;
    const latency = Date.now() - start; state.latencies.push(latency);
    log(`[${target.name}] TIMEOUT/ERROR latency=${latency}ms err=${String(e).slice(0, 80)}`);
  }
}

async function main() {
  const state = loadState();
  const burstStart = Date.now();

  // Set expected SHA on first run
  if (!state.expectedSha) {
    try {
      const resp = await fetch(TARGETS[0].url, { signal: AbortSignal.timeout(15_000) });
      const data = await resp.json() as Record<string, unknown>;
      state.expectedSha = (data.commit as string || "").slice(0, 12);
      log(`Initial SHA: ${state.expectedSha}`);
    } catch {}
  }

  log(`Burst started. Accumulated: ${Math.floor(state.accumulatedMonitoringMs / 60000)}min / 120min`);

  while (Date.now() - burstStart < BURST_DURATION_MS && state.accumulatedMonitoringMs < TARGET_DURATION_MS) {
    for (const target of TARGETS) { await checkHealth(target, state); }
    state.accumulatedMonitoringMs += INTERVAL_MS;
    saveState(state);
    if (state.accumulatedMonitoringMs < TARGET_DURATION_MS) await new Promise(r => setTimeout(r, INTERVAL_MS));
  }

  if (state.accumulatedMonitoringMs >= TARGET_DURATION_MS) {
    state.status = "completed";
    log(`SOAK COMPLETE! Total monitoring: ${state.accumulatedMonitoringMs / 60000}min`);
  }
  saveState(state);

  const pct = state.latencies.length > 0
    ? [...state.latencies].sort((a, b) => a - b)
    : [];
  const p50 = pct[Math.floor(pct.length * 0.5)] || 0;
  const p95 = pct[Math.floor(pct.length * 0.95)] || 0;
  const p99 = pct[Math.floor(pct.length * 0.99)] || 0;
  const max = pct[pct.length - 1] || 0;

  console.log(`ACCUMULATED_MIN=${Math.floor(state.accumulatedMonitoringMs / 60000)}`);
  console.log(`REMAINING_MIN=${Math.ceil((TARGET_DURATION_MS - state.accumulatedMonitoringMs) / 60000)}`);
  console.log(`TOTAL=${state.totalRequests} PASS=${state.passCount} FAIL=${state.failCount}`);
  console.log(`COLD_START_502=${state.coldStart502s} TIMEOUTS=${state.timeouts} DB_FAIL=${state.dbFailures} PROVIDER_FAIL=${state.providerFailures}`);
  console.log(`P50=${p50}ms P95=${p95}ms P99=${p99}ms MAX=${max}ms`);
  console.log(`SHA=${state.productionSha} STATUS=${state.status}`);
}

main().catch(e => { log(`FATAL: ${e}`); console.error(e); });
SCRIPT

