# ITEM 4: IVX IA Chat Deep QA
# Run comprehensive chat tests with rate-limit-safe spacing
cat > /tmp/ivx-chat-deep-qa-v2.ts << 'SCRIPT'
const BASE = "https://ivx-holdings-platform.onrender.com";
const RESULTS: { test: string; result: string; detail: string }[] = [];

async function sendChat(message: string, sessionId?: string, history?: unknown[]) {
  const body: Record<string, unknown> = { message, context: { turnCount: 1 } };
  if (sessionId) body.sessionId = sessionId;
  if (history) body.history = history;
  try {
    const resp = await fetch(`${BASE}/public/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(30_000),
    });
    const data = await resp.json() as Record<string, unknown>;
    return { ok: resp.status === 200, status: resp.status, data };
  } catch (e) {
    return { ok: false, status: 0, data: { error: String(e) } };
  }
}

async function sleep(ms: number) { return new Promise(r => setTimeout(r, ms)); }

// Test 1: New conversation
async function test1() {
  console.log("TEST 1: New conversation");
  const r = await sendChat("Hello, what is IVX Holdings?");
  const ok = r.ok && (r.data as Record<string,unknown>).ok === true;
  console.log(`  status=${r.status} ok=${ok} source=${(r.data as Record<string,unknown>).source || "?"}`);
  RESULTS.push({ test: "new_conversation", result: ok ? "PASS" : "FAIL", detail: `status=${r.status}` });
}

// Test 2: Empty message handling
async function test2() {
  console.log("TEST 2: Empty message handling");
  const r = await sendChat("");
  const ok = r.status === 400 || r.status === 422;
  console.log(`  status=${r.status} ok=${ok}`);
  RESULTS.push({ test: "empty_message", result: ok ? "PASS" : "FAIL", detail: `status=${r.status}` });
}

// Test 3: 10-turn context (using history array to simulate context)
async function test3() {
  console.log("TEST 3: 10-turn context");
  const history = [];
  let sessionId: string | undefined;
  let passCount = 0;
  for (let i = 0; i < 10; i++) {
    const msg = i === 0 ? "My name is ContextTest10 and I like commercial real estate." : `Tell me more about point ${i}`;
    const r = await sendChat(msg, sessionId, history.length > 0 ? history : undefined);
    if (r.ok) {
      const d = r.data as Record<string, unknown>;
      sessionId = (d.sessionId as string) || sessionId;
      const answer = (d.answer as string) || "";
      history.push({ role: "user", content: msg });
      history.push({ role: "assistant", content: answer });
      passCount++;
    }
    await sleep(4000); // 4s between turns to respect rate limit
  }
  // Test recall: ask for name
  const recall = await sendChat("What is my name?", sessionId, history);
  const recallAnswer = ((recall.data as Record<string, unknown>).answer as string) || "";
  const nameRecalled = recallAnswer.toLowerCase().includes("contexttest10");
  console.log(`  Turns: ${passCount}/10, Name recalled: ${nameRecalled}`);
  RESULTS.push({ test: "context_10", result: passCount === 10 ? "PASS" : "FAIL", detail: `turns=${passCount}/10 nameRecalled=${nameRecalled}` });
}

// Test 4: Rapid duplicate send
async function test4() {
  console.log("TEST 4: Rapid duplicate send (3 identical)");
  const promises = [sendChat("What is IVX?"), sendChat("What is IVX?"), sendChat("What is IVX?")];
  const results = await Promise.all(promises);
  const allOk = results.every(r => r.ok);
  console.log(`  All ok: ${allOk}, statuses: ${results.map(r => r.status).join(",")}`);
  RESULTS.push({ test: "duplicate_send", result: allOk ? "PASS" : "FAIL", detail: `statuses=${results.map(r => r.status).join(",")}` });
}

// Test 5: Rate limit enforcement
async function test5() {
  console.log("TEST 5: Rate limit enforcement (22 rapid)");
  let ok200 = 0, rateLimited429 = 0, other = 0;
  for (let i = 0; i < 22; i++) {
    try {
      const resp = await fetch(`${BASE}/public/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: `Rate test ${i}`, context: { turnCount: 1 } }),
        signal: AbortSignal.timeout(10_000),
      });
      if (resp.status === 200) ok200++;
      else if (resp.status === 429) rateLimited429++;
      else other++;
    } catch { other++; }
  }
  const enforced = rateLimited429 > 0 || ok200 <= 20;
  console.log(`  200=${ok200} 429=${rateLimited429} other=${other} enforced=${enforced}`);
  RESULTS.push({ test: "rate_limit", result: enforced ? "PASS" : "FAIL", detail: `200=${ok200} 429=${rateLimited429} other=${other}` });
}

// Test 6: Error recovery (after rate limit, wait and retry)
async function test6() {
  console.log("TEST 6: Error recovery after rate limit");
  await sleep(65000); // Wait 65s for rate limit reset
  const r = await sendChat("Recovery test after rate limit");
  const ok = r.ok && (r.data as Record<string, unknown>).ok === true;
  console.log(`  status=${r.status} ok=${ok}`);
  RESULTS.push({ test: "error_recovery", result: ok ? "PASS" : "FAIL", detail: `status=${r.status}` });
}

// Test 7: History with large payload (simulates 25+ turns of context)
async function test7() {
  console.log("TEST 7: 25-turn context via history");
  await sleep(4000);
  const history = [];
  for (let i = 0; i < 25; i++) {
    history.push({ role: "user", content: `User message ${i} about topic ${i % 5}` });
    history.push({ role: "assistant", content: `Assistant response ${i} about topic ${i % 5}` });
  }
  const r = await sendChat("Summarize our conversation", undefined, history);
  const ok = r.ok && (r.data as Record<string, unknown>).ok === true;
  const answer = ((r.data as Record<string, unknown>).answer as string) || "";
  console.log(`  status=${r.status} ok=${ok} answerLen=${answer.length}`);
  RESULTS.push({ test: "context_25", result: ok ? "PASS" : "FAIL", detail: `status=${r.status} answerLen=${answer.length}` });
}

// Test 8: 50-turn context via history
async function test8() {
  console.log("TEST 8: 50-turn context via history");
  await sleep(4000);
  const history = [];
  for (let i = 0; i < 50; i++) {
    history.push({ role: "user", content: `User message ${i}` });
    history.push({ role: "assistant", content: `Assistant response ${i}` });
  }
  const r = await sendChat("What was the first thing I said?", undefined, history);
  const ok = r.ok && (r.data as Record<string, unknown>).ok === true;
  console.log(`  status=${r.status} ok=${ok}`);
  RESULTS.push({ test: "context_50", result: ok ? "PASS" : "FAIL", detail: `status=${r.status}` });
}

// Test 9: No blank screen / no infinite loading (response has answer field)
async function test9() {
  console.log("TEST 9: No blank screen / no infinite loading");
  await sleep(4000);
  const r = await sendChat("Test for blank screen");
  const d = r.data as Record<string, unknown>;
  const hasAnswer = typeof d.answer === "string" && d.answer.length > 0;
  const hasSession = typeof d.sessionId === "string" && d.sessionId.length > 0;
  console.log(`  hasAnswer=${hasAnswer} hasSession=${hasSession}`);
  RESULTS.push({ test: "no_blank_screen", result: hasAnswer && hasSession ? "PASS" : "FAIL", detail: `answer=${hasAnswer} session=${hasSession}` });
}

// Test 10: Composer remains usable (consecutive messages work)
async function test10() {
  console.log("TEST 10: Composer remains usable (3 consecutive messages)");
  await sleep(4000);
  let passCount = 0;
  for (let i = 0; i < 3; i++) {
    const r = await sendChat(`Composer test ${i}`);
    if (r.ok) passCount++;
    await sleep(4000);
  }
  console.log(`  Consecutive: ${passCount}/3`);
  RESULTS.push({ test: "composer_usable", result: passCount === 3 ? "PASS" : "FAIL", detail: `${passCount}/3` });
}

async function main() {
  console.log("=== IVX CHAT DEEP QA v2 ===");
  console.log(`Time: ${new Date().toISOString()}`);

  await test1();
  await sleep(4000);
  await test2();
  await sleep(4000);
  await test3();
  await test4();
  await test5();
  await test6();
  await test7();
  await test8();
  await test9();
  await test10();

  console.log("\n=== CHAT DEEP QA SUMMARY ===");
  for (const r of RESULTS) console.log(`${r.test}: ${r.result} (${r.detail})`);

  const pass = RESULTS.filter(r => r.result === "PASS").length;
  const fail = RESULTS.filter(r => r.result === "FAIL").length;
  console.log(`\nTOTAL: ${pass} PASS, ${fail} FAIL out of ${RESULTS.length}`);

  const { writeFileSync } = await import("fs");
  writeFileSync("/tmp/ivx-chat-deep-qa-v2-results.json", JSON.stringify({
    timestamp: new Date().toISOString(),
    tests: RESULTS,
    passCount: pass,
    failCount: fail,
    total: RESULTS.length,
  }, null, 2));
}

main().catch(console.error);
