    const r = await sendChat(`Composer ${i}`);
    if (r.ok) passCount++;
  }
  console.log(`  Consecutive: ${passCount}/3`);
  RESULTS.push({ test: "composer_usable", result: passCount === 3 ? "PASS" : "FAIL", detail: `${passCount}/3` });

  // Test 11: Correct ordering (send messages with history, check order)
  console.log("T11: Correct ordering");
  await sleep(4000);
  const orderHist = [
    { role: "user", content: "First message about apples" },
    { role: "assistant", content: "Response about apples" },
    { role: "user", content: "Second message about bananas" },
    { role: "assistant", content: "Response about bananas" },
