# ITEM 6: Load test — 20, 50, 100 concurrent users
cat > /tmp/ivx-load-test.ts << 'SCRIPT'
const BASE = "https://ivx-holdings-platform.onrender.com";
const RESULTS: { test: string; result: string; p50: number; p95: number; p99: number; errorRate: number; timeoutRate: number; detail: string }[] = [];

async function healthCheck(): Promise<{ ok: boolean; latency: number; status: number }> {
  const start = Date.now();
  try {
    const resp = await fetch(`${BASE}/health`, { signal: AbortSignal.timeout(15_000) });
    const latency = Date.now() - start;
    return { ok: resp.status === 200, latency, status: resp.status };
  } catch {
    return { ok: false, latency: Date.now() - start, status: 0 };
  }
}

async function chatCheck(): Promise<{ ok: boolean; latency: number; status: number }> {
  const start = Date.now();
  try {
    const resp = await fetch(`${BASE}/public/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message: `Load test ${Math.random()}`, context: { turnCount: 1 } }),
      signal: AbortSignal.timeout(20_000),
    });
    const latency = Date.now() - start;
    return { ok: resp.status === 200, latency, status: resp.status };
  } catch {
    return { ok: false, latency: Date.now() - start, status: 0 };
  }
}

function percentile(arr: number[], p: number): number {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  return sorted[Math.min(Math.floor(p * sorted.length), sorted.length - 1)];
}

async function runLoadTest(concurrency: number, label: string): Promise<void> {
  console.log(`\n=== ${label}: ${concurrency} concurrent ===`);

  // Warm up with a single request
  await healthCheck();
  await new Promise(r => setTimeout(r, 3000));

  // Fire concurrent requests
  const promises: Promise<{ ok: boolean; latency: number; status: number }>[] = [];
  for (let i = 0; i < concurrency; i++) {
    promises.push(healthCheck());
  }
  const results = await Promise.all(promises);

  const latencies = results.map(r => r.latency);
  const okCount = results.filter(r => r.ok).length;
  const failCount = results.filter(r => !r.ok).length;
  const timeouts = results.filter(r => r.status === 0).length;
  const errors = results.filter(r => r.status >= 400 && r.status !== 0).length;

  const p50 = percentile(latencies, 0.5);
  const p95 = percentile(latencies, 0.95);
  const p99 = percentile(latencies, 0.99);
  const errorRate = (failCount / concurrency) * 100;
  const timeoutRate = (timeouts / concurrency) * 100;

  console.log(`  OK=${okCount} FAIL=${failCount} TIMEOUTS=${timeouts} ERRORS=${errors}`);
  console.log(`  P50=${p50}ms P95=${p95}ms P99=${p99}ms`);
  console.log(`  Error rate=${errorRate.toFixed(1)}% Timeout rate=${timeoutRate.toFixed(1)}%`);

  const statusCounts: Record<number, number> = {};
  for (const r of results) {
    statusCounts[r.status] = (statusCounts[r.status] || 0) + 1;
  }
  console.log(`  Status distribution: ${JSON.stringify(statusCounts)}`);

  const pass = errorRate < 50 && timeoutRate < 20; // Allow some 502s on free tier cold starts
  RESULTS.push({ test: label, result: pass ? "PASS" : "FAIL", p50, p95, p99, errorRate, timeoutRate, detail: `ok=${okCount} fail=${failCount} timeouts=${timeouts} statuses=${JSON.stringify(statusCounts)}` });
}

async function main() {
  console.log("=== IVX LOAD TEST ===");
  console.log(`Time: ${new Date().toISOString()}`);

  await runLoadTest(20, "20_concurrent_health");
  await new Promise(r => setTimeout(r, 5000));
  await runLoadTest(50, "50_concurrent_health");
  await new Promise(r => setTimeout(r, 5000));
  await runLoadTest(100, "100_concurrent_health");

  // Chat load test (lower concurrency due to rate limits)
  console.log("\n=== Chat load: 10 concurrent ===");
  const chatPromises: Promise<{ ok: boolean; latency: number; status: number }>[] = [];
  for (let i = 0; i < 10; i++) {
    chatPromises.push(chatCheck());
  }
  const chatResults = await Promise.all(chatPromises);
  const chatLatencies = chatResults.map(r => r.latency);
  const chatOk = chatResults.filter(r => r.ok).length;
  const chatFail = chatResults.filter(r => !r.ok).length;
  const chatStatusCounts: Record<number, number> = {};
  for (const r of chatResults) {
    chatStatusCounts[r.status] = (chatStatusCounts[r.status] || 0) + 1;
  }
  console.log(`  OK=${chatOk} FAIL=${chatFail}`);
  console.log(`  P50=${percentile(chatLatencies, 0.5)}ms P95=${percentile(chatLatencies, 0.95)}ms`);
  console.log(`  Status distribution: ${JSON.stringify(chatStatusCounts)}`);
  const chatPass = chatFail <= 5; // Allow some rate-limited responses
  RESULTS.push({ test: "10_concurrent_chat", result: chatPass ? "PASS" : "FAIL", p50: percentile(chatLatencies, 0.5), p95: percentile(chatLatencies, 0.95), p99: percentile(chatLatencies, 0.99), errorRate: (chatFail/10)*100, timeoutRate: 0, detail: `ok=${chatOk} fail=${chatFail} statuses=${JSON.stringify(chatStatusCounts)}` });

  console.log("\n=== LOAD TEST SUMMARY ===");
  for (const r of RESULTS) {
    console.log(`${r.test}: ${r.result} P50=${r.p50}ms P95=${r.p95}ms P99=${r.p99}ms ERR=${r.errorRate.toFixed(1)}% TIMEOUT=${r.timeoutRate.toFixed(1)}%`);
  }

  const { writeFileSync } = await import("fs");
  writeFileSync("/tmp/ivx-load-test-results.json", JSON.stringify({ timestamp: new Date().toISOString(), tests: RESULTS }, null, 2));
}
main().catch(console.error);
SCRIPT

