      body: JSON.stringify(body), signal: AbortSignal.timeout(25_000),
    });
    const data = await resp.json() as Record<string, unknown>;
    return { ok: resp.status === 200, status: resp.status, data };
  } catch (e) { return { ok: false, status: 0, data: { error: String(e) } }; }
}
async function sleep(ms: number) { return new Promise(r => setTimeout(r, ms)); }

async function main() {
  console.log("=== CHAT QA BATCH 3 ===");

  // Test 7: 25-turn context via history
  console.log("T7: 25-turn context");
  const hist25 = [];
  for (let i = 0; i < 25; i++) {
    hist25.push({ role: "user", content: `User msg ${i} about topic ${i%5}` });
    hist25.push({ role: "assistant", content: `Assistant response ${i}` });
  }
  const r7 = await sendChat("Summarize our conversation", hist25);
  const t7Pass = r7.ok && (r7.data as Record<string, unknown>).ok === true;
  console.log(`  status=${r7.status} ok=${t7Pass}`);
  RESULTS.push({ test: "context_25", result: t7Pass ? "PASS" : "FAIL", detail: `status=${r7.status}` });

  await sleep(4000);

  // Test 8: 50-turn context via history
  console.log("T8: 50-turn context");
  const hist50 = [];
  for (let i = 0; i < 50; i++) {
    hist50.push({ role: "user", content: `User msg ${i}` });
    hist50.push({ role: "assistant", content: `Assistant response ${i}` });
  }
  const r8 = await sendChat("What was the first thing I said?", hist50);
  const t8Pass = r8.ok && (r8.data as Record<string, unknown>).ok === true;
  console.log(`  status=${r8.status} ok=${t8Pass}`);
  RESULTS.push({ test: "context_50", result: t8Pass ? "PASS" : "FAIL", detail: `status=${r8.status}` });

  await sleep(4000);

  // Test 9: No blank screen
  console.log("T9: No blank screen");
  const r9 = await sendChat("Test blank screen");
  const d9 = r9.data as Record<string, unknown>;
  const hasAnswer = typeof d9.answer === "string" && d9.answer.length > 0;
  const hasSession = typeof d9.sessionId === "string" && d9.sessionId.length > 0;
  console.log(`  hasAnswer=${hasAnswer} hasSession=${hasSession}`);
  RESULTS.push({ test: "no_blank_screen", result: hasAnswer && hasSession ? "PASS" : "FAIL", detail: `answer=${hasAnswer} session=${hasSession}` });

  await sleep(4000);

  // Test 10: Composer usable (3 consecutive)
  console.log("T10: Composer usable");
  let passCount = 0;
  for (let i = 0; i < 3; i++) {
    const r = await sendChat(`Composer ${i}`);
    if (r.ok) passCount++;
    await sleep(4000);
  }
  console.log(`  Consecutive: ${passCount}/3`);
  RESULTS.push({ test: "composer_usable", result: passCount === 3 ? "PASS" : "FAIL", detail: `${passCount}/3` });

  // Test 11: Correct ordering
  console.log("T11: Correct ordering");
  const orderHist = [
    { role: "user", content: "First message about apples" },
    { role: "assistant", content: "Response about apples" },
    { role: "user", content: "Second message about bananas" },
    { role: "assistant", content: "Response about bananas" },
  ];
  const r11 = await sendChat("What did I ask about first?", orderHist);
  const t11Pass = r11.ok;
  console.log(`  status=${r11.status} ok=${t11Pass}`);
  RESULTS.push({ test: "correct_ordering", result: t11Pass ? "PASS" : "FAIL", detail: `status=${r11.status}` });

  // Test 12: Error recovery (chat after 400 error)
  console.log("T12: Error recovery after 400");
  await sleep(3000);
  await fetch(`${BASE}/public/chat`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message: "", context: { turnCount: 1 } }),
    signal: AbortSignal.timeout(10_000),
  });
  await sleep(3000);
  const r12 = await sendChat("Recovery after error");
  const t12Pass = r12.ok && (r12.data as Record<string, unknown>).ok === true;
  console.log(`  status=${r12.status} ok=${t12Pass}`);
  RESULTS.push({ test: "error_recovery", result: t12Pass ? "PASS" : "FAIL", detail: `status=${r12.status}` });

  const { writeFileSync } = await import("fs");
  writeFileSync("/tmp/ivx-chat-batch3-results.json", JSON.stringify({ tests: RESULTS }, null, 2));
  console.log("\nBATCH 3 SUMMARY:");
  for (const r of RESULTS) console.log(`  ${r.test}: ${r.result} (${r.detail})`);
}
main().catch(console.error);
